const body = $('Function: Input valideren en saniteren').first().json;
const customerRaw = $('Execute: Klant ophalen').first().json.stdout || '[]';
const customer = JSON.parse(customerRaw)[0] || {};
const counterRaw = $('Execute: Teller atomisch ophogen').first().json.stdout || '[{"invoice_counter":"1"}]';
const counterArr = JSON.parse(counterRaw);
const counter = counterArr[0] ? counterArr[0].invoice_counter : '1';
const settingsRaw = $('Execute: Bedrijfsinstellingen ophalen').first().json.stdout || '[{"value":""}]';
const settings = JSON.parse(settingsRaw)[0] || {};
const year = new Date().getFullYear();
const num = String(counter).padStart(4, '0');
