  body,
  customer,
  invoice_number,
  company_email: settings.value || ''
}}];

const data = $input.first().json;
const body = data.body;
const today = new Date().toISOString().split('T')[0];
const dueDate = new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0];
const regels = body.regels || [];
let subtotal = 0;
let btw_total = 0;
const regelsMet = regels.map(r => {
  const bedrag = Math.round(r.aantal * r.prijs * 100) / 100;
  const btw = Math.round(bedrag * r.btw_tarief) / 100;
  subtotal += bedrag;
  btw_total += btw;
  return { ...r, bedrag, btw };
});
subtotal = Math.round(subtotal * 100) / 100;
btw_total = Math.round(btw_total * 100) / 100;
const total = Math.round((subtotal + btw_total) * 100) / 100;
return [{ json: {
  ...data,
  regels: regelsMet,
  invoice_date: today,
  due_date: dueDate,
  subtotal,
  btw_total,
  total
}}];

function esc(str) {
  return String(str || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function eur(n) {
  return '€ ' + parseFloat(n||0).toFixed(2).replace('.',',');
}
const d = $input.first().json;
const c = d.customer || {};
const regels = d.regels || [];
const rows = regels.map(r =>
  `<tr><td>${esc(r.omschrijving)}</td><td style="text-align:right">${esc(r.aantal)}</td><td style="text-align:right">${eur(r.prijs)}</td><td style="text-align:right">${r.btw_tarief}%</td><td style="text-align:right">${eur(r.bedrag)}</td></tr>`
).join('');
const html = `<!DOCTYPE html><html lang="nl"><head><meta charset="UTF-8"><style>body{font-family:Arial,sans-serif;font-size:12px;color:#222;margin:40px}h1{color:#1a5276}.tbl{width:100%;border-collapse:collapse;margin-top:20px}.tbl th{background:#1a5276;color:#fff;padding:8px;text-align:left}.tbl td{padding:6px 8px;border-bottom:1px solid #ddd}.totals{float:right;margin-top:20px;width:300px}.totals td{padding:4px 8px}.totals .bold{font-weight:bold;border-top:2px solid #1a5276}</style></head><body><table style="width:100%"><tr><td><h1>FACTUUR</h1><p>Factuurnummer: <strong>${esc(d.invoice_number)}</strong><br>Datum: ${esc(d.invoice_date)}<br>Vervaldatum: ${esc(d.due_date)}</p></td><td style="text-align:right"><p><strong>${esc(c.name)}</strong><br>${esc(c.address)}<br>${esc(c.postal_code)} ${esc(c.city)}<br>${esc(c.country)}<br>BTW: ${esc(c.vat_number)}<br>KVK: ${esc(c.kvk_number)}</p></td></tr></table><table class="tbl"><thead><tr><th>Omschrijving</th><th style="text-align:right">Aantal</th><th style="text-align:right">Prijs</th><th style="text-align:right">BTW</th><th style="text-align:right">Bedrag</th></tr></thead><tbody>${rows}</tbody></table><table class="totals"><tr><td>Subtotaal</td><td style="text-align:right">${eur(d.subtotal)}</td></tr><tr><td>BTW</td><td style="text-align:right">${eur(d.btw_total)}</td></tr><tr class="bold"><td><strong>Totaal</strong></td><td style="text-align:right"><strong>${eur(d.total)}</strong></td></tr></table></body></html>`;
const buf = Buffer.from(html, 'utf8');
return [{ json: d, binary: { html_file: await this.helpers.prepareBinaryData(buf, 'factuur.html', 'text/html') } }];

const data = $('Function: BTW berekenen en data samenvoegen').first().json;
const regels = data.regels || [];
const inv = data.invoice_number.replace(/'/g, "''");
const item_queries = regels.map(r => {
  const omschr = String(r.omschrijving || '').replace(/'/g, "''");
  return `INSERT INTO invoice_items (invoice_number, description, quantity, unit_price, btw_rate, btw_amount, total) VALUES ('${inv}', '${omschr}', ${r.aantal}, ${r.prijs}, ${r.btw_tarief}, ${r.btw}, ${r.bedrag})`;
});
return [{ json: { item_queries } }];
